DO $$
DECLARE
    analytics_count int;
BEGIN
    LOOP
        SELECT count(*) INTO analytics_count
        FROM pg_stat_activity
        WHERE usename = 'analytics' AND state IN ('active', 'idle in transaction');
        IF analytics_count = 0 THEN
            EXIT;
        END IF;
        PERFORM pg_sleep(0.1);
    END LOOP;
    EXECUTE 'ALTER TABLE orders ALTER COLUMN customer_id SET NOT NULL';
    EXECUTE 'ALTER TABLE orders ADD CONSTRAINT fk_orders_customers FOREIGN KEY (customer_id) REFERENCES customers(id) NOT VALID';
END $$;

ALTER TABLE orders VALIDATE CONSTRAINT fk_orders_customers;

